import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"&quot;Student Portrait quan trọng hơn một danh sách KPI học tập&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/portrait-vs-kpi.md","filePath":"mental-models/portrait-vs-kpi.md"}'),c={name:"mental-models/portrait-vs-kpi.md"};function o(r,n,g,u,m,e){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="quot-student-portrait-quan-trong-hon-mot-danh-sach-kpi-hoc-tap-quot" tabindex="-1">&quot;Student Portrait quan trọng hơn một danh sách KPI học tập&quot; <a class="header-anchor" href="#quot-student-portrait-quan-trong-hon-mot-danh-sach-kpi-hoc-tap-quot" aria-label="Permalink to &quot;&amp;quot;Student Portrait quan trọng hơn một danh sách KPI học tập&amp;quot;&quot;">​</a></h1><p>Trên trang này# &quot;Student Portrait quan trọng hơn một danh sách KPI học tập&quot; <a href="#student-portrait-quan-trong-hon-mot-danh-sach-kpi-hoc-tap">​</a> Cái gì đo được sẽ được tối ưu. Đó là lý do phải rất cẩn thận với thứ mình chọn để đo — vì mọi thứ không nằm trong danh sách sẽ lặng lẽ biến mất.</p><h2 id="van-đe-cua-mot-danh-sach-chi-tieu-​" tabindex="-1">Vấn đề của một danh sách chỉ tiêu <a href="#van-đe-cua-mot-danh-sach-chi-tieu">​</a> <a class="header-anchor" href="#van-đe-cua-mot-danh-sach-chi-tieu-​" aria-label="Permalink to &quot;Vấn đề của một danh sách chỉ tiêu [​](#van-đe-cua-mot-danh-sach-chi-tieu)&quot;">​</a></h2><p>Giả sử một gia đình đặt ra bộ chỉ tiêu cho năm học: textToán ≥ 8.5 Văn ≥ 7.5 Anh ≥ 8.0 IELTS 6.5 trước tháng 6 Học thêm đủ 3 buổi/tuầnRõ ràng, đo được, theo dõi được. Và có bốn vấn đề: <strong>Nó bỏ sót gần hết những gì quan trọng.</strong> Con có tò mò không? Có dám hỏi khi không hiểu không? Có bạn không? Ngủ đủ không? Không chỉ tiêu nào chạm tới những thứ này — nên chúng trở thành thứ &quot;không tính&quot;. <strong>Nó khuyến khích đường tắt.</strong> &quot;Toán ≥ 8.5&quot; đạt được nhanh nhất bằng cách học tủ và luyện dạng, không phải bằng cách hiểu sâu. Chỉ tiêu không phân biệt hai con đường đó. <strong>Nó tạo quan hệ đối kháng.</strong> Chỉ tiêu là thứ người lớn đặt và đứa trẻ phải đạt. Không đạt là thất bại của con. Trong khi phần lớn nguyên nhân thường nằm ở chỗ khác — nền hổng, cách học sai, hoặc chỉ tiêu đặt không thực tế. <strong>Nó hết hạn.</strong> Cuối năm học, cả danh sách trở nên vô nghĩa và phải viết lại từ đầu.</p><h2 id="portrait-lam-khac-the-nao-​" tabindex="-1">Portrait làm khác thế nào <a href="#portrait-lam-khac-the-nao">​</a> <a class="header-anchor" href="#portrait-lam-khac-the-nao-​" aria-label="Permalink to &quot;Portrait làm khác thế nào [​](#portrait-lam-khac-the-nao)&quot;">​</a></h2><p>Portrait mô tả <strong>một con người</strong>, không phải một tập chỉ số. Nó bao gồm cả mục tiêu học thuật — nhưng đặt chúng cạnh chín mảng khác, nên không mảng nào chiếm hết chỗ. Danh sách KPIStudent PortraitTrả lời câu hỏiCon đạt được gì?Con trở thành ai?Thời hạnMột học kỳNhiều nămAi đặt raNgười lớnCả nhà, có con tham giaĐạt bằng đường tắtĐượcKhôngKhi không đạtThất bạiThông tin để điều chỉnhPhạm viNhững gì trường đoCả cuộc sống</p><h2 id="nhung-van-can-con-so-​" tabindex="-1">Nhưng vẫn cần con số <a href="#nhung-van-can-con-so">​</a> <a class="header-anchor" href="#nhung-van-can-con-so-​" aria-label="Permalink to &quot;Nhưng vẫn cần con số [​](#nhung-van-can-con-so)&quot;">​</a></h2><p>Portrait mà không có mốc cụ thể thì chỉ là một danh sách mong ước dễ chịu. Đây là chỗ <a href="/portrait/milestone">milestone</a> vào cuộc — nhưng với một khác biệt quan trọng so với KPI: <strong>Milestone phục vụ Portrait, không thay thế nó.</strong> &quot;IELTS 6.5 vào tháng 6&quot; là một milestone. Nó tồn tại vì Portrait ghi <em>&quot;con muốn học đại học ở nước ngoài&quot;</em>. Khi biết mốc đó phục vụ điều gì, ba chuyện đổi:</p><ul><li>Nếu hoàn cảnh thay đổi, mốc điều chỉnh được — vì mục đích vẫn còn đó.</li><li>Nó không phải thứ phải đạt bằng mọi giá; nó là một bước trên đường.</li><li>Con hiểu vì sao mình làm việc này — và đó là khác biệt lớn nhất về động lực. Còn một KPI trần trụi &quot;IELTS 6.5&quot; không phục vụ điều gì cả ngoài chính nó.</li></ul><h2 id="cai-gi-đo-đuoc-se-đuoc-toi-uu-​" tabindex="-1">Cái gì đo được sẽ được tối ưu <a href="#cai-gi-đo-đuoc-se-đuoc-toi-uu">​</a> <a class="header-anchor" href="#cai-gi-đo-đuoc-se-đuoc-toi-uu-​" aria-label="Permalink to &quot;Cái gì đo được sẽ được tối ưu [​](#cai-gi-đo-đuoc-se-đuoc-toi-uu)&quot;">​</a></h2><p>Đây là quy luật đáng nhớ nhất trong trang này, và nó đúng ở mọi tổ chức, không riêng gia đình. Nếu thứ duy nhất được đo và nhắc tới là điểm số, thì:</p><ul><li>Con sẽ tối ưu điểm số — kể cả bằng cách không tạo ra hiểu biết.</li><li>Con sẽ tránh những việc có ích nhưng không cho điểm.</li><li>Con sẽ tin rằng giá trị của mình là điểm số của mình. Điều thứ ba là hệ quả nghiêm trọng nhất, và nó là cơ chế trực tiếp đằng sau việc một đứa trẻ sụp đổ sau một kỳ thi trượt. Portrait mở rộng cái được đo. Khi &quot;dám hỏi khi không hiểu&quot; cũng là một mốc được theo dõi, nó trở thành một việc đáng làm — thay vì một thứ không ai để ý.</li></ul><h2 id="nemo12-giu-ranh-gioi-nay-​" tabindex="-1">Nemo12 giữ ranh giới này <a href="#nemo12-giu-ranh-gioi-nay">​</a> <a class="header-anchor" href="#nemo12-giu-ranh-gioi-nay-​" aria-label="Permalink to &quot;Nemo12 giữ ranh giới này [​](#nemo12-giu-ranh-gioi-nay)&quot;">​</a></h2><p><strong>Portrait không tự động thành mục tiêu của hệ thống.</strong> Viết vào Portrait là bày tỏ nguyện vọng. Chỉ khi gia đình chốt rõ ràng, một phần mới thành mục tiêu vận hành. Không có chuyện âm thầm chuyển ước mơ thành chỉ tiêu. <strong>Nguyện vọng được giữ nguyên khi không thực tế.</strong> Hệ thống điều chỉnh các mốc trung gian, không xoá mong muốn của gia đình. <strong>Ý muốn của con lưu riêng.</strong> Không trộn với ý muốn của bố mẹ thành một con số trung bình — vì chỗ hai bên không đồng ý mới là chỗ đáng nói chuyện nhất. <strong>Bất đồng được nêu ra, không tự dàn xếp.</strong> Hệ thống chỉ ra chỗ lệch và gợi ý trò chuyện. Nó không phán ai đúng. Thử một lần Viết ra ba điều bạn muốn con trở thành trong năm năm tới — <strong>không dùng bất kỳ con số nào</strong>. Nếu khó, đó chính là điều đáng chú ý: cái khung KPI đã chiếm chỗ của cái khung Portrait, và nó làm việc đó rất lặng lẽ. Chỉ tiêu cho biết con đang ở đâu so với một con số. Portrait cho biết con đang đi đâu. Chỉ có câu thứ hai là còn được hỏi khi con ba mươi tuổi. <a href="/mental-models/">Quay lại đầu nhóm →</a></p>',14)])])}const k=t(c,[["render",o]]);export{l as __pageData,k as default};
